export KUBECONFIG="${KUBECONFIG:-$HOME/.kube/s145.yaml}"
POD=$(kubectl -n immich get pod -l app=immich-public-proxy -o jsonpath='{.items[0].metadata.name}')
IP=$(kubectl -n immich get svc immich-server -o jsonpath='{.spec.clusterIP}')
echo "POD=$POD CLUSTERIP=$IP"
# Node fetch tests - this is what IPP uses
kubectl -n immich exec "$POD" -- node -e "
const urls = [
  'http://immich-server.immich.svc.cluster.local:2283/api/server/ping',
  'http://immich-server:2283/api/server/ping',
  'http://$IP:2283/api/server/ping',
];
(async () => {
  for (const u of urls) {
    try {
      const r = await fetch(u);
      const t = await r.text();
      console.log('OK', u, r.status, t);
    } catch (e) {
      console.log('FAIL', u, e.name, e.message, e.cause && e.cause.code, e.cause && e.cause.message);
    }
  }
})();
" 2>&1
echo '=== recent IPP errors sample ==='
kubectl -n immich logs "$POD" --tail=30 2>&1 | rg -i 'Unable to reach|fetch failed|IMMICH|status' | head -20

# get assetFetchUrl / auth from source
curl -fsSL --max-time 20 'https://raw.githubusercontent.com/alangrainger/immich-public-proxy/v3.2.0/app/src/immich.ts' | rg -n 'assetFetchUrl|authHeadersForAsset|function getShare|thumbnail|/assets/' | head -50
# extract those functions
curl -fsSL --max-time 20 'https://raw.githubusercontent.com/alangrainger/immich-public-proxy/v3.2.0/app/src/immich.ts' > /tmp/ipp-immich.ts
python3 <<'PY'
from pathlib import Path
text = Path('/tmp/ipp-immich.ts').read_text()
for name in ['assetFetchUrl', 'authHeadersForAsset', 'getShareByKey']:
    i = text.find(f'export async function {name}')
    if i < 0: i = text.find(f'export function {name}')
    if i < 0: i = text.find(f'async function {name}')
    if i < 0: i = text.find(f'function {name}')
    print('====', name, 'at', i)
    if i>=0: print(text[i:i+1200]); print('...')
PY

export KUBECONFIG="${KUBECONFIG:-$HOME/.kube/s145.yaml}"
POD=$(kubectl -n immich get pod -l app=immich-public-proxy -o jsonpath='{.items[0].metadata.name}')
KEY='REDACTED'
ASSET='30cf1f69-364d-43c3-b844-778b5de013cd'

# Reproduce thumbnail with full cause + also hit Immich asset endpoint patterns
kubectl -n immich exec "$POD" -- node -e "
const KEY='$KEY';
const ASSET='$ASSET';
const base='http://immich-server.immich.svc.cluster.local:2283';
(async()=>{
  // shared link me
  let r = await fetch(base+'/api/shared-links/me?key='+KEY);
  console.log('shared-links/me', r.status);
  const link = await r.json();
  console.log('link keys', Object.keys(link));
  console.log('assets?', Array.isArray(link.assets)? link.assets.length : typeof link.assets, 'type', link.type);

  // try common thumbnail URLs
  const urls = [
    base+'/api/assets/'+ASSET+'/thumbnail?size=thumbnail',
    base+'/api/assets/'+ASSET+'/thumbnail',
    base+'/api/assets/'+ASSET+'/original',
  ];
  for (const u of urls) {
    try {
      const h = { 'x-immich-share-key': KEY };
      const res = await fetch(u, { headers: h });
      console.log('GET', u.replace(base,''), res.status, res.headers.get('content-type'), 'len', res.headers.get('content-length'));
    } catch(e) {
      console.log('FAIL', u, e.message, e.cause && e.cause.code, e.cause && e.cause.message);
    }
  }

  // parallel stampede like gallery
  const N=40;
  const start=Date.now();
  const results = await Promise.all(Array.from({length:N}, async (_,i)=>{
    try {
      const res = await fetch(base+'/api/assets/'+ASSET+'/thumbnail?size=thumbnail', { headers: { 'x-immich-share-key': KEY }});
      return res.status;
    } catch(e) {
      return 'ERR:'+(e.cause&&e.cause.code||e.message);
    }
  }));
  console.log('parallel', N, 'in', Date.now()-start,'ms', 'sample', results.slice(0,10), 'fails', results.filter(x=>String(x).startsWith('ERR')).length, 'non200', results.filter(x=>x!==200).length);
})().catch(e=>console.error(e));
" 2>&1

export KUBECONFIG="${KUBECONFIG:-$HOME/.kube/s145.yaml}"
POD=$(kubectl -n immich get pod -l app=immich-public-proxy -o jsonpath='{.items[0].metadata.name}')
KEY='REDACTED'
ASSET='30cf1f69-364d-43c3-b844-778b5de013cd'
# error cause breakdown
kubectl -n immich exec "$POD" -- node -e "
const KEY='$KEY', ASSET='$ASSET';
const u='http://immich-server.immich.svc.cluster.local:2283/api/assets/'+ASSET+'/thumbnail?size=thumbnail';
const counts={};
(async()=>{
  const results=await Promise.all(Array.from({length:60}, async()=>{
    try {
      const res=await fetch(u,{headers:{'x-immich-share-key':KEY}});
      return 'HTTP_'+res.status;
    } catch(e){
      const c=e.cause||{};
      const k=(c.code||c.message||e.message||'unknown').toString();
      return 'ERR_'+k;
    }
  }));
  for (const r of results) counts[r]=(counts[r]||0)+1;
  console.log(counts);
})();
" 2>&1

